//! The destination selector's consumer side (`design/d1-ghost.md` §4.1).
//!
//! The MODE table is GENERATED by `d1-oracle activity-modes write` from block 1063 of the packages
//! (that generator, its shape guards and its 21-launchable / 393-413 pins live in
//! `d1-server/crates/d1-oracle/src/activity_modes.rs`). This module only READS the shipped TSV -
//! the same split as `d1guest.py` reading `item-content-index.tsv` that `d1-oracle item-index`
//! writes. Ghost never generates it.
//!
//! ⛔ **Non-launchable entries are greyed, not hidden**, each carrying the client's own refusal
//! reason - the selector doubles as the honest reachability map (Patrol appears, greyed, with
//! "matchmaking required"). Gate: `Launch` entries enable only at `setup:orbit` with liveness L3.

use std::path::Path;

/// The default TSV path, relative to the repo root - must match `activity_modes::DEFAULT_PATH`.
pub const DEFAULT_PATH: &str = "capture-rig/activity-modes.tsv";

/// The exact column header the generator writes (`activity_modes::TSV_COLUMNS`). Restated here as
/// the format contract between the two crates; if it drifts, [`parse`] rejects the file loudly
/// rather than reading shifted columns.
pub const TSV_COLUMNS: &str = "index\thash\tlaunchable\tcontent_family\tmode_name";

/// The pinned launchable band, so the consumer can recognise a well-formed table without the dump.
pub const LAUNCHABLE_FIRST: usize = 393;
pub const LAUNCHABLE_LAST: usize = 413;

/// One selectable destination row.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Destination {
    pub index: usize,
    pub hash: u32,
    /// `activity_def[+0xA9] == 0`: rung 29 skips matchmaking, so this index can be launched.
    pub launchable: bool,
    pub content_family: u8,
    /// The pinned display name for the 21 launchable indices; empty for the rest.
    pub mode_name: String,
}

impl Destination {
    /// The refusal reason a greyed (non-launchable) entry renders with. Nonempty exactly when the
    /// entry is not launchable, so the selector can never grey a row without saying why.
    pub fn refusal(&self) -> String {
        if self.launchable {
            String::new()
        } else {
            format!("+0xA9 != 0 (matchmaking required); content family {}", self.content_family)
        }
    }

    /// The label the button shows: the mode name if we have one, else the bare index.
    pub fn label(&self) -> String {
        if self.mode_name.is_empty() {
            format!("activity {}", self.index)
        } else {
            format!("{} ({})", self.mode_name, self.index)
        }
    }
}

/// The parsed selector table.
#[derive(Debug, Clone, Default)]
pub struct Destinations {
    pub rows: Vec<Destination>,
    /// A note carried for the panel: absent file, parse error, or the count summary.
    pub note: String,
}

impl Destinations {
    /// The launchable rows, in order - what the selector offers as enabled buttons.
    pub fn launchable(&self) -> Vec<&Destination> {
        self.rows.iter().filter(|d| d.launchable).collect()
    }

    /// Load the shipped TSV. A missing file is NOT an error - it means the generator has not been
    /// run in this checkout (the output is gitignored). The selector renders the note and offers
    /// no destinations, rather than pretending the table is empty.
    pub fn load(repo_root: &Path) -> Destinations {
        let path = repo_root.join(DEFAULT_PATH);
        match std::fs::read_to_string(&path) {
            Ok(text) => match parse(&text) {
                Ok(rows) => {
                    let n = rows.iter().filter(|d| d.launchable).count();
                    Destinations {
                        rows,
                        note: format!("{} destinations, {n} launchable", 0),
                    }
                    .with_count()
                }
                Err(e) => Destinations {
                    rows: Vec::new(),
                    note: format!("⛔ {} is present but does not parse: {e}", path.display()),
                },
            },
            Err(_) => Destinations {
                rows: Vec::new(),
                note: format!(
                    "no {} yet - run `d1-oracle activity-modes write` (needs the owned-media dump)",
                    DEFAULT_PATH
                ),
            },
        }
    }

    fn with_count(mut self) -> Destinations {
        let n = self.rows.iter().filter(|d| d.launchable).count();
        self.note = format!("{} destinations, {n} launchable", self.rows.len());
        self
    }
}

/// Parse the shipped TSV, checking the column header matches [`TSV_COLUMNS`]. A wrong header is an
/// error, never a silent shifted read.
pub fn parse(text: &str) -> Result<Vec<Destination>, String> {
    let mut saw_header = false;
    let mut out = Vec::new();
    for line in text.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        if !saw_header {
            if line != TSV_COLUMNS {
                return Err(format!("column header {line:?} != expected {TSV_COLUMNS:?}"));
            }
            saw_header = true;
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() != 5 {
            return Err(format!("row has {} fields, want 5: {line:?}", f.len()));
        }
        let index = f[0].parse::<usize>().map_err(|e| format!("index: {e}"))?;
        let hash = u32::from_str_radix(f[1].trim_start_matches("0x"), 16).map_err(|e| format!("hash: {e}"))?;
        let launchable = f[2] == "1";
        let content_family = f[3].parse::<u8>().map_err(|e| format!("family: {e}"))?;
        out.push(Destination { index, hash, launchable, content_family, mode_name: f[4].to_string() });
    }
    if !saw_header {
        return Err("no column header line".to_string());
    }
    Ok(out)
}

/// The 32 PvP map stems (`activity-launch.md` §2.2, `[C]` from the package inventory). The stem IS
/// the world-name string published at `blob+0x688` - it is not a pretty label, it is the value the
/// Activity Host serves. A launch is a MODE (one of the 21 activity indices) crossed with one of
/// these MAPs.
///
/// ⚠ Unresolved count: this inventory yields 32; `package-container-pvp-content.md` §7.5 enumerates
/// 33. Carried, not reconciled (same discrepancy the design doc flags).
pub const PVP_MAPS: &[&str] = &[
    "pvp_anomaly", "pvp_arena_hive", "pvp_breach", "pvp_cabal_camp", "pvp_city_defense",
    "pvp_colony_ship", "pvp_cosmobattle", "pvp_den", "pvp_dos", "pvp_eq",
    "pvp_factory", "pvp_greenhouse", "pvp_hive_cell", "pvp_icarus", "pvp_ketch",
    "pvp_longshot", "pvp_marsbattle", "pvp_moonbase", "pvp_oasis", "pvp_outskirts",
    "pvp_refinery", "pvp_rift", "pvp_rooftops", "pvp_srl_mars01", "pvp_srl_venus01",
    "pvp_subway", "pvp_tomb", "pvp_venus_hcc", "pvp_vertigo", "pvp_vex_tube",
    "pvp_well", "pvp_wilderness_town",
];

/// The map that has been run in-world (`pvp_moonbase x 407` is `observed-live`); every other pair
/// is untried `[U]`.
pub const MAP_OBSERVED_LIVE: &str = "pvp_moonbase";

/// A readable label for a `pvp_*` stem: drop the prefix, split on `_`, title-case. The stem itself
/// is kept visible because IT is what gets served - the label is only for the eye. We do NOT invent
/// retail marketing names we cannot verify; this is a mechanical de-slug.
pub fn map_label(stem: &str) -> String {
    let body = stem.strip_prefix("pvp_").unwrap_or(stem);
    let pretty = body
        .split('_')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ");
    format!("{pretty} ({stem})")
}

/// A small fixture in the exact generator format, for the headless C-GHOST-DESTS control: two
/// non-launchable rows (Tower 0, Patrol 7) and one launchable (Elimination 407).
pub const FIXTURE_TSV: &str = "\
# generated fixture
index\thash\tlaunchable\tcontent_family\tmode_name
0\t0x8ae8da69\t0\t0\t
7\t0x11111111\t0\t4\t
407\t0x6d714c3a\t1\t0\tElimination
";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fixture_parses_and_greys_correctly() {
        let rows = parse(FIXTURE_TSV).unwrap();
        assert_eq!(rows.len(), 3);
        let elim = rows.iter().find(|d| d.index == 407).unwrap();
        assert!(elim.launchable && elim.mode_name == "Elimination");
        assert!(elim.refusal().is_empty(), "a launchable entry carries no refusal");
        let tower = rows.iter().find(|d| d.index == 0).unwrap();
        assert!(!tower.launchable);
        assert!(tower.refusal().contains("matchmaking"), "a greyed entry must say why");
    }

    #[test]
    fn a_wrong_header_is_rejected() {
        assert!(parse("index\thash\n1\t0x2\n").is_err());
    }

    #[test]
    fn map_list_and_labels() {
        assert_eq!(PVP_MAPS.len(), 32, "the pinned inventory is 32 stems");
        assert!(PVP_MAPS.contains(&MAP_OBSERVED_LIVE));
        assert_eq!(map_label("pvp_moonbase"), "Moonbase (pvp_moonbase)");
        assert_eq!(map_label("pvp_wilderness_town"), "Wilderness Town (pvp_wilderness_town)");
        // no duplicates
        let mut seen = std::collections::HashSet::new();
        for m in PVP_MAPS {
            assert!(seen.insert(*m), "duplicate map stem {m}");
        }
    }

    #[test]
    fn label_falls_back_to_the_index() {
        let named = Destination { index: 407, hash: 0, launchable: true, content_family: 0, mode_name: "Elimination".into() };
        let anon = Destination { index: 5, hash: 0, launchable: false, content_family: 4, mode_name: String::new() };
        assert_eq!(named.label(), "Elimination (407)");
        assert_eq!(anon.label(), "activity 5");
    }
}
